// GTNH fluid icons: picks a texture and a tint for every fluid in the recipes.
//
// RecEx gives fluid ids and names but no colours, and NEI shows no fluids. GregTech's jar has a
// texture per fluid for some (most already coloured), and grey "autogenerated" textures (plain,
// molten, plasma) that GregTech tints with the fluid's colour. The colour comes from:
//   - molten.* / plasma.*: the material's colour (materials.json, from gtnh-materials.mjs)
//   - anything else: the fluid's cell in the NEI dump ("Hydrogen" -> "Hydrogen Cell"), whose window
//     shows the fluid colour
//
// Usage: node scripts/gtnh-fluids.mjs [references/GTNH]   (run gtnh-materials.mjs first)
// Writes: <dir>/fluids.json { "<fluid id>": { name, texture, tint, from } }
//   texture is a path under gt-textures/assets/gregtech/textures/blocks/fluids (first frame is used)
import fs from 'node:fs';
import path from 'node:path';
import { createRequire } from 'node:module';

const require = createRequire(new URL('../promo/package.json', import.meta.url));
const { loadImage, createCanvas } = require('@napi-rs/canvas');

const dir = process.argv[2] ?? 'references/GTNH';
const FLUIDS = path.join(dir, 'gt-textures/assets/gregtech/textures/blocks/fluids');
const materials = JSON.parse(fs.readFileSync(path.join(dir, 'materials.json'), 'utf8'));
const matByName = new Map(Object.values(materials).filter((m) => m.set).map((m) => [m.name.toLowerCase(), m]));

// ---------------------------------------------------------------- textures
const textures = new Set(fs.readdirSync(FLUIDS).filter((f) => f.endsWith('.png')).map((f) => f.slice(0, -4)));
const pixelCache = new Map();
async function pixels(file) {
  if (pixelCache.has(file)) return pixelCache.get(file);
  let out = null;
  if (fs.existsSync(file)) {
    const img = await loadImage(file);
    const c = createCanvas(16, 16), g = c.getContext('2d');
    g.imageSmoothingEnabled = false;
    g.drawImage(img, 0, 0, img.width, img.width, 0, 0, 16, 16); // first frame of animated strips
    out = g.getImageData(0, 0, 16, 16).data;
  }
  pixelCache.set(file, out);
  return out;
}
const saturation = (d) => { let s = 0; for (let i = 0; i < d.length; i += 4) s += Math.max(d[i], d[i + 1], d[i + 2]) - Math.min(d[i], d[i + 1], d[i + 2]); return s / 256; };
const greyTexture = new Map();
for (const t of textures) greyTexture.set(t, saturation(await pixels(path.join(FLUIDS, `${t}.png`))) < 8);

// ---------------------------------------------------------------- NEI dump: cell icons by name
const parseCsv = (line) => { const out = []; let cur = '', q = false; for (const ch of line) { if (ch === '"') { q = !q; continue; } if (ch === ',' && !q) { out.push(cur); cur = ''; continue; } cur += ch; } out.push(cur); return out; };
const illegal = new Set([...'<>:"/\\|?*'].map((c) => c.charCodeAt(0)));
const cleanName = (n) => [...n].map((ch) => (illegal.has(ch.charCodeAt(0)) || ch.charCodeAt(0) < 32 ? '_' : ch)).join('');
const cells = new Map(); // lower-case fluid name -> { file, key }
let emptyCell = null;
{
  const seen = new Map();
  for (const r of fs.readFileSync(path.join(dir, 'itempanel.csv'), 'utf8').trim().split(/\r?\n/).slice(1).map(parseCsv)) {
    const name = r.slice(4).join(',');
    const base = cleanName(name); const n = seen.get(base) ?? 1; seen.set(base, n + 1);
    const file = path.join(dir, 'icons', n > 1 ? `${base}_${n}.png` : `${base}.png`);
    if (r[0] === 'gregtech:gt.metaitem.01' && name === 'Empty Cell') emptyCell ??= file;
    const m = name.match(/^(.*) Cell$/);
    if (m && !cells.has(m[1].toLowerCase())) cells.set(m[1].toLowerCase(), { file, key: `${r[0]}:${r[2]}` });
  }
}

const hex = (rgb) => '#' + rgb.map((v) => Math.max(0, Math.min(255, Math.round(v))).toString(16).padStart(2, '0')).join('');
/** Fluid colour from a cell icon: the pixels that differ from the empty cell are the fluid window. */
async function cellColour(file) {
  const icon = await pixels(file), empty = emptyCell && (await pixels(emptyCell));
  if (!icon) return null;
  const sum = [0, 0, 0]; let n = 0;
  for (let p = 0; p < 256; p++) {
    const i = p * 4;
    if (icon[i + 3] < 128) continue;
    const diff = !empty || empty[i + 3] < 128 || Math.abs(icon[i] - empty[i]) + Math.abs(icon[i + 1] - empty[i + 1]) + Math.abs(icon[i + 2] - empty[i + 2]) > 30;
    if (!diff) continue;
    for (let ch = 0; ch < 3; ch++) sum[ch] += icon[i + ch]; n++;
  }
  if (n < 3) return null;
  // The cell's fluid window is drawn a little darker than the fluid texture itself.
  return hex(sum.map((v) => (v / n) / 0.8));
}

// ---------------------------------------------------------------- every fluid in the recipes
const recex = JSON.parse(fs.readFileSync(path.join(dir, 'recex-2.8.4.json'), 'utf8'));
const fluids = new Map();
for (const m of recex.sources[0].machines) for (const r of m.recs) for (const f of [...r.fI, ...r.fO]) fluids.set(f.id, f.lN);

const VANILLA = { water: { texture: 'minecraft:blocks/water_still', tint: '#3f76e4' }, lava: { texture: 'minecraft:blocks/lava_still', tint: null } };
// Minecraft's dye colours, for the chemical dye fluids.
const DYES = { Black: '#1d1d21', Red: '#b02e26', Green: '#5e7c16', Brown: '#835432', Blue: '#3c44aa', Purple: '#8932b8', Cyan: '#169c9c', 'Light Gray': '#9d9d97', Gray: '#474f52', Pink: '#f38baa', Lime: '#80c71f', Yellow: '#fed83d', 'Light Blue': '#3ab3da', Magenta: '#c74ebd', Orange: '#f9801d', White: '#f9fffe' };
const result = {};
const counts = {};
const bump = (k) => (counts[k] = (counts[k] ?? 0) + 1);
for (const [id, name] of [...fluids].sort()) {
  const own = [`fluid.${id}`, `fluid.fluid.${id.replace(/^fluid\./, '')}`, id].find((t) => textures.has(t));
  // Vanilla water and lava keep Minecraft's own textures (water is tinted blue in the game too).
  if (VANILLA[id]) { result[id] = { name, ...VANILLA[id], from: 'minecraft' }; bump('minecraft texture'); continue; }
  // GregTech's molten.iron and Tinkers' iron.molten are both molten metals.
  const kind = id.startsWith('molten.') || id.endsWith('.molten') ? 'molten' : id.startsWith('plasma.') ? 'plasma' : 'plain';
  const matName = name.replace(/^Molten /, '').replace(/ Plasma$/, '').replace(/Aluminum/g, 'Aluminium').toLowerCase();

  // Colour: the material (molten / plasma), else the cell.
  let tint = null, from = null;
  if (kind !== 'plain' && matByName.get(matName)) { tint = matByName.get(matName).color; from = 'material'; }
  if (!tint) {
    const cell = cells.get(name.toLowerCase()) ?? cells.get(matName);
    if (cell) { tint = await cellColour(cell.file); if (tint) from = `cell ${cell.key}`; }
  }
  if (!tint && kind !== 'plain' && matByName.get(matName)) { tint = matByName.get(matName).color; from = 'material'; }
  const dye = name.match(/(Black|Light Blue|Blue|Brown|Cyan|Light Gray|Gray|Green|Lime|Magenta|Orange|Pink|Purple|Red|White|Yellow) Dye/);
  if (!tint && dye) { tint = DYES[dye[1]]; from = 'dye colour'; }

  if (own && !greyTexture.get(own)) { result[id] = { name, texture: own, tint: null, from: 'texture' }; bump('own coloured texture'); continue; }
  const texture = own ?? `fluid.${kind === 'plain' ? '' : kind + '.'}autogenerated`;
  result[id] = { name, texture, tint: tint ?? '#9aa4b2', from: from ?? 'default grey' };
  bump(tint ? `${own ? 'own grey' : kind} texture, ${from.split(' ')[0]} colour` : 'no colour found');
}

fs.writeFileSync(path.join(dir, 'fluids.json'), JSON.stringify(result, null, 1));
console.log(`fluids ${fluids.size}`);
for (const [k, v] of Object.entries(counts).sort((a, b) => b[1] - a[1])) console.log(`  ${v}  ${k}`);
